import inspect

def get_calibrator(name: str, config_path: Optional[str] = None) -> Calibrator:
    if name not in CALIBRATOR_REGISTRY:
        raise ValueError(f"Unknown calibrator: {name}")
    kwargs: Dict[str, Any] = {}
    if config_path and os.path.exists(config_path):
        try:
            with open(config_path, "r", encoding="utf-8") as f:
                raw = json.load(f)
            sig = inspect.signature(CALIBRATOR_REGISTRY[name].__init__)
            kwargs = {k: v for k, v in raw.items() if k in sig.parameters}
        except Exception as e:
            logger.warning(f"Failed to load calibrator config: {e}")
    return CALIBRATOR_REGISTRY[name](**kwargs)
